package android.graphics.drawable;import android.content.res.Resources;import java.util.*;public class AnimationDrawable extends Drawable {public final List<Drawable> frames=new ArrayList<Drawable>();public final List<Integer> delays=new ArrayList<Integer>();public boolean running,once;public void setOneShot(boolean b){once=b;}public void addFrame(Drawable d,int ms){frames.add(d);delays.add(ms);}public boolean isRunning(){return running;}public void start(){running=true;}public void stop(){running=false;}public ConstantState getConstantState(){final AnimationDrawable me=this;return new ConstantState(){public Drawable newDrawable(Resources r){AnimationDrawable result=new AnimationDrawable();result.once=me.once;for(int i=0;i<me.frames.size();i++)result.addFrame(new BitmapDrawable(r,((BitmapDrawable)me.frames.get(i)).bitmap),me.delays.get(i));return result;}};}}